verify.cmd:
node --experimental-strip-types --no-warnings --import ./scripts/probe-ts.mjs -e 'const fs=require("fs")
const fail=(m)=>{console.error("LIVE-689: "+m);process.exit(1)}
const rd=(f)=>{if(!fs.existsSync(f))fail(f+" is gone");return fs.readFileSync(f,"utf8")}
const strip=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
if(!fs.existsSync("lib/journeys/block-order.ts"))fail("lib/journeys/block-order.ts does not exist, so the builder and the member player share no one ordering over practices and blocks")
const A=strip(rd("app/(main)/journeys/[slug]/edit/actions.ts"))
const body=(name)=>{const i=A.indexOf("export async function "+name+"(");if(i<0)return "";const j=A.indexOf("\nexport ",i+10);return A.slice(i,j<0?undefined:j)}
if(!body("reorderBlocksAction"))fail("the edit actions have no reorderBlocksAction, so a drag cannot save a lane order")
if(!/planSiblingOrder\(/.test(body("reorderBlocksAction"))||!/writeLaneOrder\(/.test(body("reorderBlocksAction")))fail("reorderBlocksAction does not check the lane with planSiblingOrder and write it through writeLaneOrder")
if(!/moveWithin\(/.test(body("moveBlockAction"))||!/writeLaneOrder\(/.test(body("moveBlockAction")))fail("moveBlockAction does not move within the lane through the shared writer")
const E=strip(rd("components/journey/v2/journey-editor.tsx"))
if(!/builderSegments\(/.test(E))fail("the builder does not draw a phase through builderSegments, so what it draws is not the order the member reads")
if(!/reorderBlocksAction\(/.test(E)||!/draggable/.test(E))fail("the builder has no drag that saves through reorderBlocksAction")
if(/practiceLeaves|isPracticeLeaf/.test(E))fail("the builder still gathers practices into their own group after the lessons")
const J=rd("lib/journey-plans.ts")
if(/interleaving with practices is a follow-up/.test(J))fail("the follow-up note is still in lib/journey-plans.ts")
if(/practiceIdsInOrder/.test(J))fail("lib/journey-plans.ts still carries a reorder that takes practice ids only")
Promise.all([import("@/lib/journeys/block-order.ts"),import("@/lib/journeys/tree.ts")]).then(([O,T])=>{
const B=(id,p,t,s)=>({id,parentId:p,blockType:t,sortOrder:s})
const js=[B("p1",null,"phase",0),B("breathe","p1","practice",0),B("intro","p1","lesson",1),B("walk","p1","practice",2),B("m1","p1","module",3),B("m1-read","m1","reading",0),B("m1-sit","m1","practice",1),B("recap","p1","check",4),B("p2",null,"phase",1),B("p2-sit","p2","practice",0),B("opening",null,"lesson",2)]
const rows=(bs)=>bs.map((b)=>({id:b.id,parent_id:b.parentId,block_type:b.blockType,sort_order:b.sortOrder,title:b.id,required:true,est_minutes:null,practice_id:b.blockType==="practice"?"x-"+b.id:null}))
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b)
const tree=(bs)=>T.buildJourneyTree(rows(bs),[]).lessonOrder
const want=["opening","breathe","intro","walk","m1-read","m1-sit","recap","p2-sit"]
if(!same(tree(js),want))fail("the member player does not read practices and lessons interleaved in stored order: "+tree(js).join(","))
if(!same(O.builderLeafOrder(js),want))fail("the builder draws "+O.builderLeafOrder(js).join(",")+" and the member reads "+want.join(","))
const lane=O.childrenInOrder(js,"p1").map((b)=>({id:b.id,sort_order:b.sortOrder}))
const next=O.moveTo(O.moveTo(lane.map((r)=>r.id),"intro","breathe"),"recap","walk")
const w=next&&O.planSiblingOrder(lane,next)
if(!w)fail("a drag of a lesson above a practice was refused")
const after=js.map((b)=>{const x=w.find((y)=>y.id===b.id);return x?{...b,sortOrder:x.to}:b})
const want2=["opening","intro","breathe","recap","walk","m1-read","m1-sit","p2-sit"]
if(!same(tree(after),want2))fail("after the drag the member reads "+tree(after).join(","))
if(!same(O.builderLeafOrder(after),want2))fail("after the drag the builder draws "+O.builderLeafOrder(after).join(","))
const swap=O.moveWithin(lane.map((r)=>r.id),"breathe","down")
const sw=swap&&O.planSiblingOrder(lane,swap)
if(!sw||sw.length!==2)fail("an arrow swap of a practice and a lesson does not write exactly two rows")
if(O.planSiblingOrder(lane,next.slice(1))!==null||O.planSiblingOrder(lane,[...next.slice(1),"forged"])!==null||O.planSiblingOrder(lane,[next[0],...next.slice(0,-1)])!==null)fail("a stale, forged or repeated order is accepted")
if(O.laneOf(null,"lesson")===O.laneOf(null,"phase"))fail("a loose step and a phase share a lane, so an arrow can swap a step with a phase the builder does not draw beside it")
console.log("ok: practices, lessons and modules share one stored order; the builder draws the member reading order before and after a drag; an arrow swap writes two rows; stale, forged and repeated orders are refused")
}).catch((e)=>fail("could not load the ordering modules: "+(e&&e.message)))'
